const crypto=require('node:crypto');const fs=require('node:fs');
const digest=(value)=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
function verifyBundle(payload,publicKey){if(!payload||payload.schemaVersion!==1||!digest(payload.reportSha256)||typeof payload.reportB64!=='string'||typeof payload.signatureB64!=='string')throw new Error('Oversight dispatch schema is invalid.');const bytes=Buffer.from(payload.reportB64,'base64');if(bytes.length>50000)throw new Error('Oversight report exceeds the bounded intake size.');const actual=crypto.createHash('sha256').update(bytes).digest('hex');if(actual!==payload.reportSha256)throw new Error('Oversight report hash mismatch.');if(!crypto.verify(null,bytes,publicKey,Buffer.from(payload.signatureB64,'base64')))throw new Error('Oversight signature is invalid.');const report=JSON.parse(bytes.toString('utf8'));if(report.schemaVersion!==1||report.independent!==true||report.assimilatedRecords!==0||report.proofStageSatisfied!==false||report.oversight?.state!=='passed'||report.oversight?.action!=='NONE'||!Array.isArray(report.manifests))throw new Error('Oversight report is not eligible for intake.');const approvals=[];for(const manifest of report.manifests){if(manifest.state!=='structurally-vetted-candidate-only'||manifest.independentSourcesSatisfied!==true||manifest.promotionAuthorized!==false||manifest.proofStageSatisfied!==false)continue;for(const source of manifest.sourceReviews||[]){if(!digest(source.contentSha256)||source.automaticallyTrusted!==false)throw new Error('Vetted source decision is invalid.');approvals.push({contentSha256:source.contentSha256,decision:'approved-for-extraction',oversightReportSha256:actual,candidateId:manifest.candidateId,decidedAt:report.generatedAt});}}return{reportSha256:actual,approvals};}
function mergeLedger(file,result){const prior=fs.existsSync(file)?JSON.parse(fs.readFileSync(file,'utf8')):{schemaVersion:1,projectId:'github:jonathanblunt1214-lgtm/The-Crucible',approvals:[]};if(prior.schemaVersion!==1||prior.projectId!=='github:jonathanblunt1214-lgtm/The-Crucible'||!Array.isArray(prior.approvals))throw new Error('Oversight approval ledger is invalid.');const keyed=new Map(prior.approvals.map((item)=>[`${item.contentSha256}:${item.oversightReportSha256}`,item]));for(const item of result.approvals)keyed.set(`${item.contentSha256}:${item.oversightReportSha256}`,item);const next={...prior,approvals:[...keyed.values()],updatedAt:new Date().toISOString()};const temporary=`${file}.${process.pid}.tmp`;fs.writeFileSync(temporary,`${JSON.stringify(next,null,2)}\n`,{flag:'wx',mode:0o600});fs.renameSync(temporary,file);return next;}
if(require.main===module){try{const [eventFile,publicKeyFile,ledgerFile]=process.argv.slice(2);if(!eventFile||!publicKeyFile||!ledgerFile)throw new Error('Usage: verify-oversight-bundle.js <event> <public-key> <ledger>');const event=JSON.parse(fs.readFileSync(eventFile,'utf8'));const result=verifyBundle(event.client_payload,fs.readFileSync(publicKeyFile));console.log(JSON.stringify({reportSha256:result.reportSha256,accepted:result.approvals.length,total:mergeLedger(ledgerFile,result).approvals.length}));}catch(error){console.error(error.message);process.exitCode=1;}}
module.exports={verifyBundle,mergeLedger};
